DO $dairy$
DECLARE payload jsonb := $payload$[{"language": "es", "slug": "yogur-griego-casero", "public_path": "/yogur-griego-casero", "title": "Yogur griego casero: cómo escurrir yogur natural", "excerpt": "Convierte yogur natural en yogur griego casero sin espesantes. Fotos del escurrido en nevera, rendimiento aproximado y consejos para aprovechar el suero.", "summary": "Escurrir yogur natural retira parte del suero y concentra la textura. De 1 kg salen aproximadamente 450–600 g; esta ficha calcula 500 g. Usa yogur natural sin azúcar, comprado o hecho con nuestra receta y ya frío.", "content_html": "<p>Escurrir yogur natural retira parte del suero y concentra la textura. De 1 kg salen aproximadamente 450–600 g; esta ficha calcula 500 g. Usa yogur natural sin azúcar, comprado o hecho con nuestra receta y ya frío.</p>", "notes": "<h3>Consejos y conservación</h3><p>Consume en 3–4 días y nunca después de la fecha del yogur de partida. El suero es ácido: úsalo refrigerado en 1–2 días en masas o batidos si está en buen estado. No es crema para hacer mantequilla. Sin prueba de cocina propia. Contiene leche. Usa utensilios limpios y desinfectados y conserva a 4 °C o menos. No es una conserva para guardar a temperatura ambiente.</p><ul><li><a href=\"https://www.uaf.edu/ces/publications/database/food/making-yogurt.php\">University of Alaska Fairbanks — yogurt preparation and refrigeration</a></li><li><a href=\"https://nutritionsource.hsph.harvard.edu/food-features/yogurt/\">Harvard Nutrition Source — yogurt and strained yogurt</a></li></ul>", "ingredients": [{"name": "yogur natural entero sin azúcar, frío", "amount": "1000", "unit": "g"}], "steps": [{"title": "Prepara el colador", "content": "Lava y desinfecta bol y colador. Coloca una tela fina limpia apta para alimentos en el colador, apoyado sobre un bol profundo. El fondo de la tela debe quedar separado del líquido que caiga.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-01.webp", "image_alt": "Prepara el colador — Yogur griego casero: cómo escurrir yogur natural"}, {"title": "Añade el yogur", "content": "Vierte el yogur frío en la tela sin batirlo. Junta los bordes de la tela y cubre el conjunto sin apretar. No añadas leche ni agua.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-02.webp", "image_alt": "Añade el yogur — Yogur griego casero: cómo escurrir yogur natural"}, {"title": "Escurre en la nevera", "content": "Refrigera a 4 °C o menos durante 4–6 horas. Revisa el espesor desde las 4 horas y retira suero del bol si alcanza el colador. No escurras sobre la mesa a temperatura ambiente.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-03.webp", "image_alt": "Escurre en la nevera — Yogur griego casero: cómo escurrir yogur natural"}, {"title": "Alisa y guarda", "content": "Pasa a un recipiente limpio y mezcla suavemente. Para aligerar, reincorpora un poco del suero reservado. Tapa y mantén frío. El tiempo total de la ficha cuenta 6 horas de escurrido.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-04.webp", "image_alt": "Alisa y guarda — Yogur griego casero: cómo escurrir yogur natural"}], "category": "Postres", "course": "Postres", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 10, "cook_time_minutes": 0, "total_time_minutes": 370, "servings": 5, "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "alt": "Yogur griego casero: cómo escurrir yogur natural"}], "video_urls": [], "keywords": ["Yogur griego casero: cómo escurrir yogur natural"], "nutrition": {"calories": 97, "protein_g": 9, "carbs_g": 4, "fat_g": 5, "serving_size": "1 de 5 porciones, unos 100 g", "estimated": true, "note": "Estimación por porción; el rendimiento, la humedad y la marca cambian los valores.", "source": "USDA FoodData Central generic plain whole-milk Greek yogurt proxy", "method": "Reference finished strained yogurt per 100 g: 97 kcal, 9 g protein, 4 g carbohydrate, 5 g fat. Five 100 g portions assume 500 g yield from 1000 g natural yogurt. Whey excluded; no exact nutrient retention measured. Draining and starting yogurt alter composition."}, "seo": {"title": "Yogur griego casero: cómo escurrir yogur natural", "description": "Convierte yogur natural en yogur griego casero sin espesantes. Fotos del escurrido en nevera, rendimiento aproximado y consejos para aprovechar el suero.", "author": "Néstor Bastidas", "image_alt": "Yogur griego casero: cómo escurrir yogur natural", "image_variants": ["https://manualdecocina.com/recetas/yogur-griego-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-16x9.webp"], "faq": [{"q": "¿Necesito otro cultivo?", "a": "No, se parte de yogur ya fermentado. La receta de yogur natural explica cómo hacerlo desde leche."}, {"q": "¿Cuanto más escurro, más rinde?", "a": "Al contrario: queda más espeso y disminuye el peso final."}], "additional_time_minutes": 360}, "published": false, "editorial_status": "ready"}, {"language": "en", "slug": "homemade-strained-greek-yogurt", "public_path": "/en/homemade-strained-greek-yogurt", "title": "Homemade Greek-style yogurt by straining", "excerpt": "Turn plain yogurt into thick Greek-style yogurt without thickeners. Photos show refrigerator straining, approximate yield and practical ways to use the whey.", "summary": "Straining removes some whey and thickens plain yogurt. One kilogram yields about 450–600 g; this recipe assumes 500 g. Start with chilled unsweetened whole-milk yogurt, purchased or made with our plain-yogurt recipe.", "content_html": "<p>Straining removes some whey and thickens plain yogurt. One kilogram yields about 450–600 g; this recipe assumes 500 g. Start with chilled unsweetened whole-milk yogurt, purchased or made with our plain-yogurt recipe.</p>", "notes": "<h3>Tips and storage</h3><p>Use within 3–4 days and never beyond the starting yogurt&#x27;s use-by date. Refrigerate the acidic whey and use within 1–2 days in dough or smoothies if sound. It cannot replace cream for butter. Not kitchen-tested. Contains milk. Use clean, sanitized equipment and refrigerate at 4 °C or below. This is not a shelf-stable canned product.</p><ul><li><a href=\"https://www.uaf.edu/ces/publications/database/food/making-yogurt.php\">University of Alaska Fairbanks — yogurt preparation and refrigeration</a></li><li><a href=\"https://nutritionsource.hsph.harvard.edu/food-features/yogurt/\">Harvard Nutrition Source — yogurt and strained yogurt</a></li></ul>", "ingredients": [{"name": "chilled unsweetened whole-milk plain yogurt", "amount": "1000", "unit": "g"}], "steps": [{"title": "Prepare the strainer", "content": "Wash and sanitize bowl and strainer. Line the strainer with clean fine food-safe cloth over a deep bowl. Leave enough clearance so the cloth does not touch the draining liquid.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-01.webp", "image_alt": "Prepare the strainer — Homemade Greek-style yogurt by straining"}, {"title": "Add the yogurt", "content": "Spoon cold yogurt into the cloth without beating. Gather the cloth edges and cover without squeezing. Do not add milk or water.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-02.webp", "image_alt": "Add the yogurt — Homemade Greek-style yogurt by straining"}, {"title": "Drain in the refrigerator", "content": "Refrigerate at 4 °C or below for 4–6 hours. Check thickness after 4 hours and empty whey if it reaches the strainer. Do not strain at room temperature.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-03.webp", "image_alt": "Drain in the refrigerator — Homemade Greek-style yogurt by straining"}, {"title": "Smooth and store", "content": "Transfer to a clean container and stir gently. Thin with a little reserved whey if desired. Cover and keep chilled. Total time includes 6 hours of draining.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-04.webp", "image_alt": "Smooth and store — Homemade Greek-style yogurt by straining"}], "category": "Desserts", "course": "Desserts", "cuisine": "International", "difficulty": "Easy", "prep_time_minutes": 10, "cook_time_minutes": 0, "total_time_minutes": 370, "servings": 5, "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "alt": "Homemade Greek-style yogurt by straining"}], "video_urls": [], "keywords": ["Homemade Greek-style yogurt by straining"], "nutrition": {"calories": 97, "protein_g": 9, "carbs_g": 4, "fat_g": 5, "serving_size": "1 of 5 servings, about 100 g", "estimated": true, "note": "Estimated per serving; yield, moisture and brands affect the values.", "source": "USDA FoodData Central generic plain whole-milk Greek yogurt proxy", "method": "Reference finished strained yogurt per 100 g: 97 kcal, 9 g protein, 4 g carbohydrate, 5 g fat. Five 100 g portions assume 500 g yield from 1000 g natural yogurt. Whey excluded; no exact nutrient retention measured. Draining and starting yogurt alter composition."}, "seo": {"title": "Homemade Greek-style yogurt by straining", "description": "Turn plain yogurt into thick Greek-style yogurt without thickeners. Photos show refrigerator straining, approximate yield and practical ways to use the whey.", "author": "Néstor Bastidas", "image_alt": "Homemade Greek-style yogurt by straining", "image_variants": ["https://manualdecocina.com/recetas/yogur-griego-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-16x9.webp"], "faq": [{"q": "Do I need another starter?", "a": "No. Begin with fermented yogurt; our plain-yogurt recipe explains starting with milk."}, {"q": "Does longer draining increase yield?", "a": "No. It makes a thicker yogurt and reduces the finished weight."}], "additional_time_minutes": 360}, "published": false, "editorial_status": "ready"}, {"language": "de", "slug": "griechischer-joghurt-selber-machen", "public_path": "/de/griechischer-joghurt-selber-machen", "title": "Griechischen Joghurt durch Abtropfen selber machen", "excerpt": "Naturjoghurt ohne Verdickungsmittel zu griechischem Joghurt verarbeiten. Fotos zeigen Abtropfen im Kühlschrank, ungefähre Ausbeute und Verwendung der Molke.", "summary": "Abtropfen entfernt Molke und macht Naturjoghurt dicker. Ein Kilogramm ergibt etwa 450–600 g; hier werden 500 g angenommen. Verwende kalten ungesüßten Vollmilchjoghurt, gekauft oder nach unserem Grundrezept hergestellt.", "content_html": "<p>Abtropfen entfernt Molke und macht Naturjoghurt dicker. Ein Kilogramm ergibt etwa 450–600 g; hier werden 500 g angenommen. Verwende kalten ungesüßten Vollmilchjoghurt, gekauft oder nach unserem Grundrezept hergestellt.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>In 3–4 Tagen verbrauchen, spätestens zum Verbrauchsdatum des Ausgangsjoghurts. Saure Molke gekühlt in 1–2 Tagen in Teigen oder Smoothies verwenden, wenn einwandfrei. Sie ersetzt keine Sahne zur Butterherstellung. Nicht küchenerprobt. Enthält Milch. Saubere, desinfizierte Geräte verwenden und bei höchstens 4 °C lagern. Dies ist keine ungekühlt haltbare Konserve.</p><ul><li><a href=\"https://www.uaf.edu/ces/publications/database/food/making-yogurt.php\">University of Alaska Fairbanks — yogurt preparation and refrigeration</a></li><li><a href=\"https://nutritionsource.hsph.harvard.edu/food-features/yogurt/\">Harvard Nutrition Source — yogurt and strained yogurt</a></li></ul>", "ingredients": [{"name": "kalter ungesüßter Vollmilch-Naturjoghurt", "amount": "1000", "unit": "g"}], "steps": [{"title": "Sieb vorbereiten", "content": "Schüssel und Sieb reinigen und desinfizieren. Ein feines sauberes lebensmittelechtes Tuch ins Sieb über einer tiefen Schüssel legen. Das Tuch darf die ablaufende Flüssigkeit nicht berühren.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-01.webp", "image_alt": "Sieb vorbereiten — Griechischen Joghurt durch Abtropfen selber machen"}, {"title": "Joghurt einfüllen", "content": "Kalten Joghurt ohne Aufschlagen ins Tuch geben. Tuchränder zusammenlegen und locker abdecken. Keine Milch oder Wasser zugeben.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-02.webp", "image_alt": "Joghurt einfüllen — Griechischen Joghurt durch Abtropfen selber machen"}, {"title": "Gekühlt abtropfen", "content": "Bei höchstens 4 °C 4–6 Stunden abtropfen lassen. Ab 4 Stunden Konsistenz prüfen und Molke abgießen, bevor sie das Sieb erreicht. Nicht bei Zimmertemperatur abtropfen lassen.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-03.webp", "image_alt": "Gekühlt abtropfen — Griechischen Joghurt durch Abtropfen selber machen"}, {"title": "Glatt rühren und lagern", "content": "In einen sauberen Behälter geben und sanft verrühren. Bei Bedarf etwas Molke zurückgeben. Abdecken und kalt halten. Die Gesamtzeit umfasst 6 Stunden Abtropfen.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-04.webp", "image_alt": "Glatt rühren und lagern — Griechischen Joghurt durch Abtropfen selber machen"}], "category": "Desserts", "course": "Desserts", "cuisine": "International", "difficulty": "Einfach", "prep_time_minutes": 10, "cook_time_minutes": 0, "total_time_minutes": 370, "servings": 5, "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "alt": "Griechischen Joghurt durch Abtropfen selber machen"}], "video_urls": [], "keywords": ["Griechischen Joghurt durch Abtropfen selber machen"], "nutrition": {"calories": 97, "protein_g": 9, "carbs_g": 4, "fat_g": 5, "serving_size": "1 von 5 Portionen, etwa 100 g", "estimated": true, "note": "Schätzung pro Portion; Ausbeute, Feuchtigkeit und Produkte beeinflussen die Werte.", "source": "USDA FoodData Central generic plain whole-milk Greek yogurt proxy", "method": "Reference finished strained yogurt per 100 g: 97 kcal, 9 g protein, 4 g carbohydrate, 5 g fat. Five 100 g portions assume 500 g yield from 1000 g natural yogurt. Whey excluded; no exact nutrient retention measured. Draining and starting yogurt alter composition."}, "seo": {"title": "Griechischen Joghurt durch Abtropfen selber machen", "description": "Naturjoghurt ohne Verdickungsmittel zu griechischem Joghurt verarbeiten. Fotos zeigen Abtropfen im Kühlschrank, ungefähre Ausbeute und Verwendung der Molke.", "author": "Néstor Bastidas", "image_alt": "Griechischen Joghurt durch Abtropfen selber machen", "image_variants": ["https://manualdecocina.com/recetas/yogur-griego-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-16x9.webp"], "faq": [{"q": "Brauche ich neue Kulturen?", "a": "Nein. Der Joghurt ist bereits fermentiert; das Grundrezept erklärt den Weg von der Milch."}, {"q": "Bringt längeres Abtropfen mehr Ausbeute?", "a": "Nein, es ergibt festeren Joghurt mit weniger Gewicht."}], "additional_time_minutes": 360}, "published": false, "editorial_status": "ready"}, {"language": "fr", "slug": "yaourt-grec-maison-egoutte", "public_path": "/fr/yaourt-grec-maison-egoutte", "title": "Yaourt à la grecque maison par égouttage", "excerpt": "Transformez un yaourt nature en yaourt épais sans épaississant. Photos de l'égouttage au réfrigérateur, rendement approximatif et utilisation du petit-lait.", "summary": "L'égouttage retire une partie du petit-lait et épaissit le yaourt nature. Un kilogramme donne environ 450–600 g ; cette fiche compte 500 g. Utilisez du yaourt entier nature non sucré, acheté ou fait maison, déjà froid.", "content_html": "<p>L&#x27;égouttage retire une partie du petit-lait et épaissit le yaourt nature. Un kilogramme donne environ 450–600 g ; cette fiche compte 500 g. Utilisez du yaourt entier nature non sucré, acheté ou fait maison, déjà froid.</p>", "notes": "<h3>Conseils et conservation</h3><p>Consommez sous 3–4 jours sans dépasser la date du yaourt initial. Gardez le petit-lait acide au frais et utilisez sous 1–2 jours dans une pâte ou un smoothie s&#x27;il est sain. Il ne remplace pas la crème pour le beurre. Non testée en cuisine. Contient du lait. Utilisez du matériel propre et désinfecté et conservez à 4 °C maximum. Cette préparation ne se conserve pas à température ambiante.</p><ul><li><a href=\"https://www.uaf.edu/ces/publications/database/food/making-yogurt.php\">University of Alaska Fairbanks — yogurt preparation and refrigeration</a></li><li><a href=\"https://nutritionsource.hsph.harvard.edu/food-features/yogurt/\">Harvard Nutrition Source — yogurt and strained yogurt</a></li></ul>", "ingredients": [{"name": "yaourt entier nature non sucré, froid", "amount": "1000", "unit": "g"}], "steps": [{"title": "Préparez la passoire", "content": "Nettoyez et désinfectez bol et passoire. Tapissez la passoire d'un tissu fin propre apte au contact alimentaire, au-dessus d'un bol profond. Le tissu ne doit pas toucher le liquide recueilli.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-01.webp", "image_alt": "Préparez la passoire — Yaourt à la grecque maison par égouttage"}, {"title": "Ajoutez le yaourt", "content": "Versez le yaourt froid sans le fouetter. Rassemblez les bords du tissu et couvrez sans serrer. N'ajoutez ni lait ni eau.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-02.webp", "image_alt": "Ajoutez le yaourt — Yaourt à la grecque maison par égouttage"}, {"title": "Égouttez au réfrigérateur", "content": "Maintenez à 4 °C maximum pendant 4–6 heures. Vérifiez dès 4 heures et videz le petit-lait avant qu'il n'atteigne la passoire. Ne laissez pas égoutter à température ambiante.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-03.webp", "image_alt": "Égouttez au réfrigérateur — Yaourt à la grecque maison par égouttage"}, {"title": "Lissez et conservez", "content": "Transférez dans un récipient propre et mélangez doucement. Détendez avec un peu de petit-lait si souhaité. Couvrez et gardez au frais. Le temps total compte 6 heures d'égouttage.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-04.webp", "image_alt": "Lissez et conservez — Yaourt à la grecque maison par égouttage"}], "category": "Desserts", "course": "Desserts", "cuisine": "Internationale", "difficulty": "Facile", "prep_time_minutes": 10, "cook_time_minutes": 0, "total_time_minutes": 370, "servings": 5, "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "alt": "Yaourt à la grecque maison par égouttage"}], "video_urls": [], "keywords": ["Yaourt à la grecque maison par égouttage"], "nutrition": {"calories": 97, "protein_g": 9, "carbs_g": 4, "fat_g": 5, "serving_size": "1 des 5 portions, environ 100 g", "estimated": true, "note": "Estimation par portion ; rendement, humidité et marques modifient les valeurs.", "source": "USDA FoodData Central generic plain whole-milk Greek yogurt proxy", "method": "Reference finished strained yogurt per 100 g: 97 kcal, 9 g protein, 4 g carbohydrate, 5 g fat. Five 100 g portions assume 500 g yield from 1000 g natural yogurt. Whey excluded; no exact nutrient retention measured. Draining and starting yogurt alter composition."}, "seo": {"title": "Yaourt à la grecque maison par égouttage", "description": "Transformez un yaourt nature en yaourt épais sans épaississant. Photos de l'égouttage au réfrigérateur, rendement approximatif et utilisation du petit-lait.", "author": "Néstor Bastidas", "image_alt": "Yaourt à la grecque maison par égouttage", "image_variants": ["https://manualdecocina.com/recetas/yogur-griego-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-16x9.webp"], "faq": [{"q": "Faut-il ajouter des ferments ?", "a": "Non. Le yaourt est déjà fermenté ; la recette de yaourt nature explique sa fabrication à partir de lait."}, {"q": "Un égouttage plus long augmente-t-il le rendement ?", "a": "Non. Le yaourt épaissit mais pèse moins."}], "additional_time_minutes": 360}, "published": false, "editorial_status": "ready"}, {"language": "it", "slug": "yogurt-greco-fatto-in-casa", "public_path": "/it/yogurt-greco-fatto-in-casa", "title": "Yogurt greco fatto in casa scolando yogurt bianco", "excerpt": "Trasforma yogurt bianco in yogurt greco denso senza addensanti. Foto della scolatura in frigorifero, resa indicativa e consigli per utilizzare il siero.", "summary": "Scolare lo yogurt elimina parte del siero e concentra la consistenza. Da 1 kg si ottengono circa 450–600 g; qui si calcolano 500 g. Parti da yogurt intero bianco non zuccherato, acquistato o fatto in casa e già freddo.", "content_html": "<p>Scolare lo yogurt elimina parte del siero e concentra la consistenza. Da 1 kg si ottengono circa 450–600 g; qui si calcolano 500 g. Parti da yogurt intero bianco non zuccherato, acquistato o fatto in casa e già freddo.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Consuma entro 3–4 giorni, senza superare la scadenza dello yogurt iniziale. Il siero acido si può usare refrigerato in 1–2 giorni in impasti o frullati, se in buono stato. Non sostituisce la panna per il burro. Non testata in cucina. Contiene latte. Usa utensili puliti e igienizzati e conserva a 4 °C o meno. Non è una conserva da tenere a temperatura ambiente.</p><ul><li><a href=\"https://www.uaf.edu/ces/publications/database/food/making-yogurt.php\">University of Alaska Fairbanks — yogurt preparation and refrigeration</a></li><li><a href=\"https://nutritionsource.hsph.harvard.edu/food-features/yogurt/\">Harvard Nutrition Source — yogurt and strained yogurt</a></li></ul>", "ingredients": [{"name": "yogurt bianco intero non zuccherato, freddo", "amount": "1000", "unit": "g"}], "steps": [{"title": "Prepara il colino", "content": "Lava e igienizza ciotola e colino. Rivesti con un telo fine pulito per alimenti sopra una ciotola profonda. Il telo non deve toccare il liquido raccolto.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-01.webp", "image_alt": "Prepara il colino — Yogurt greco fatto in casa scolando yogurt bianco"}, {"title": "Aggiungi lo yogurt", "content": "Versa lo yogurt freddo senza montarlo. Raccogli i bordi del telo e copri senza stringere. Non aggiungere latte né acqua.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-02.webp", "image_alt": "Aggiungi lo yogurt — Yogurt greco fatto in casa scolando yogurt bianco"}, {"title": "Scola in frigorifero", "content": "Mantieni a 4 °C o meno per 4–6 ore. Controlla la consistenza dopo 4 ore e svuota il siero prima che tocchi il colino. Non scolare a temperatura ambiente.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-03.webp", "image_alt": "Scola in frigorifero — Yogurt greco fatto in casa scolando yogurt bianco"}, {"title": "Liscia e conserva", "content": "Passa in un contenitore pulito e mescola piano. Se serve, ammorbidisci con poco siero tenuto da parte. Copri e mantieni freddo. Il totale include 6 ore di scolatura.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-04.webp", "image_alt": "Liscia e conserva — Yogurt greco fatto in casa scolando yogurt bianco"}], "category": "Dolci", "course": "Dolci", "cuisine": "Internazionale", "difficulty": "Facile", "prep_time_minutes": 10, "cook_time_minutes": 0, "total_time_minutes": 370, "servings": 5, "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "alt": "Yogurt greco fatto in casa scolando yogurt bianco"}], "video_urls": [], "keywords": ["Yogurt greco fatto in casa scolando yogurt bianco"], "nutrition": {"calories": 97, "protein_g": 9, "carbs_g": 4, "fat_g": 5, "serving_size": "1 di 5 porzioni, circa 100 g", "estimated": true, "note": "Stima per porzione; resa, umidità e prodotti possono cambiare i valori.", "source": "USDA FoodData Central generic plain whole-milk Greek yogurt proxy", "method": "Reference finished strained yogurt per 100 g: 97 kcal, 9 g protein, 4 g carbohydrate, 5 g fat. Five 100 g portions assume 500 g yield from 1000 g natural yogurt. Whey excluded; no exact nutrient retention measured. Draining and starting yogurt alter composition."}, "seo": {"title": "Yogurt greco fatto in casa scolando yogurt bianco", "description": "Trasforma yogurt bianco in yogurt greco denso senza addensanti. Foto della scolatura in frigorifero, resa indicativa e consigli per utilizzare il siero.", "author": "Néstor Bastidas", "image_alt": "Yogurt greco fatto in casa scolando yogurt bianco", "image_variants": ["https://manualdecocina.com/recetas/yogur-griego-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-16x9.webp"], "faq": [{"q": "Servono altri fermenti?", "a": "No. Parti da yogurt già fermentato; la ricetta dello yogurt bianco spiega come farlo dal latte."}, {"q": "Più scolo, più yogurt ottengo?", "a": "No. Diventa più denso ma diminuisce il peso finale."}], "additional_time_minutes": 360}, "published": false, "editorial_status": "ready"}, {"language": "ja", "slug": "homemade-strained-greek-yogurt", "public_path": "/ja/homemade-strained-greek-yogurt", "title": "プレーンヨーグルトで作る自家製ギリシャヨーグルト", "excerpt": "プレーンヨーグルトを冷蔵庫で水切りし、とろりと濃厚なギリシャ風に。増粘剤なしで作る工程を写真で説明し、出来上がり量と残った乳清の使い方も紹介します。", "summary": "プレーンヨーグルトの乳清を一部除き、濃厚にします。1 kgから約450〜600 g、ここでは500 gを想定します。市販または自家製の、冷たい無糖全乳ヨーグルトを使います。", "content_html": "<p>プレーンヨーグルトの乳清を一部除き、濃厚にします。1 kgから約450〜600 g、ここでは500 gを想定します。市販または自家製の、冷たい無糖全乳ヨーグルトを使います。</p>", "notes": "<h3>コツと保存</h3><p>3〜4日以内、かつ元のヨーグルトの期限内に食べます。酸味のある乳清は冷蔵して1〜2日以内に、生地やスムージーに使えますが、状態を確認してください。バター用クリームの代わりにはなりません。調理試験は行っていません。 乳を含みます。清潔に洗浄・消毒した器具を使い、4 ℃以下で冷蔵してください。常温保存用の瓶詰めではありません。</p><ul><li><a href=\"https://www.uaf.edu/ces/publications/database/food/making-yogurt.php\">University of Alaska Fairbanks — yogurt preparation and refrigeration</a></li><li><a href=\"https://nutritionsource.hsph.harvard.edu/food-features/yogurt/\">Harvard Nutrition Source — yogurt and strained yogurt</a></li></ul>", "ingredients": [{"name": "冷たい無糖の全乳プレーンヨーグルト", "amount": "1000", "unit": "g"}], "steps": [{"title": "ざるを用意する", "content": "ボウルとざるを洗浄・消毒します。深いボウルにざるを重ね、清潔な食品用の目の細かい布を敷きます。布が下の液体に触れない高さにします。", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-01.webp", "image_alt": "ざるを用意する — プレーンヨーグルトで作る自家製ギリシャヨーグルト"}, {"title": "ヨーグルトを入れる", "content": "冷たいヨーグルトを泡立てずに布へ入れます。布の縁を寄せて、強く絞らずに覆います。牛乳や水は加えません。", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-02.webp", "image_alt": "ヨーグルトを入れる — プレーンヨーグルトで作る自家製ギリシャヨーグルト"}, {"title": "冷蔵庫で水切りする", "content": "4 ℃以下で4〜6時間水切りします。4時間から固さを確認し、乳清がざるに届く前に捨てるか取り分けます。室温では水切りしません。", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-03.webp", "image_alt": "冷蔵庫で水切りする — プレーンヨーグルトで作る自家製ギリシャヨーグルト"}, {"title": "滑らかにして保存する", "content": "清潔な容器へ移して優しく混ぜます。柔らかくしたいときは乳清を少量戻します。ふたをして冷蔵します。合計時間は水切り6時間で計算しています。", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-04.webp", "image_alt": "滑らかにして保存する — プレーンヨーグルトで作る自家製ギリシャヨーグルト"}], "category": "デザート", "course": "デザート", "cuisine": "各国料理", "difficulty": "簡単", "prep_time_minutes": 10, "cook_time_minutes": 0, "total_time_minutes": 370, "servings": 5, "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "alt": "プレーンヨーグルトで作る自家製ギリシャヨーグルト"}], "video_urls": [], "keywords": ["プレーンヨーグルトで作る自家製ギリシャヨーグルト"], "nutrition": {"calories": 97, "protein_g": 9, "carbs_g": 4, "fat_g": 5, "serving_size": "5食分の1、約100 g", "estimated": true, "note": "1食分の推定値です。出来上がり量、水分、製品により異なります。", "source": "USDA FoodData Central generic plain whole-milk Greek yogurt proxy", "method": "Reference finished strained yogurt per 100 g: 97 kcal, 9 g protein, 4 g carbohydrate, 5 g fat. Five 100 g portions assume 500 g yield from 1000 g natural yogurt. Whey excluded; no exact nutrient retention measured. Draining and starting yogurt alter composition."}, "seo": {"title": "プレーンヨーグルトで作る自家製ギリシャヨーグルト", "description": "プレーンヨーグルトを冷蔵庫で水切りし、とろりと濃厚なギリシャ風に。増粘剤なしで作る工程を写真で説明し、出来上がり量と残った乳清の使い方も紹介します。", "author": "Néstor Bastidas", "image_alt": "プレーンヨーグルトで作る自家製ギリシャヨーグルト", "image_variants": ["https://manualdecocina.com/recetas/yogur-griego-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-16x9.webp"], "faq": [{"q": "新しく菌を加えますか。", "a": "いいえ。発酵済みのヨーグルトを使います。牛乳からの作り方はプレーンヨーグルトのレシピにあります。"}, {"q": "長く水切りすると量が増えますか。", "a": "逆です。濃くなりますが、出来上がりの重さは減ります。"}], "additional_time_minutes": 360}, "published": false, "editorial_status": "ready"}, {"language": "pt", "slug": "iogurte-grego-caseiro", "public_path": "/pt/iogurte-grego-caseiro", "title": "Iogurte grego caseiro escorrendo iogurte natural", "excerpt": "Transforme iogurte natural em iogurte grego sem espessantes. Fotos mostram a drenagem na geladeira, rendimento aproximado e formas de aproveitar o soro.", "summary": "Escorrer retira parte do soro e concentra o iogurte natural. Um quilo rende cerca de 450–600 g; aqui calculamos 500 g. Use iogurte integral natural sem açúcar, comprado ou caseiro, já frio.", "content_html": "<p>Escorrer retira parte do soro e concentra o iogurte natural. Um quilo rende cerca de 450–600 g; aqui calculamos 500 g. Use iogurte integral natural sem açúcar, comprado ou caseiro, já frio.</p>", "notes": "<h3>Dicas e conservação</h3><p>Consuma em 3–4 dias sem ultrapassar a validade do iogurte inicial. Use o soro ácido refrigerado em 1–2 dias em massas ou vitaminas, se estiver em bom estado. Não substitui creme para manteiga. Sem teste de cozinha próprio. Contém leite. Use utensílios limpos e higienizados e conserve a 4 °C ou menos. Não é uma conserva para guardar à temperatura ambiente.</p><ul><li><a href=\"https://www.uaf.edu/ces/publications/database/food/making-yogurt.php\">University of Alaska Fairbanks — yogurt preparation and refrigeration</a></li><li><a href=\"https://nutritionsource.hsph.harvard.edu/food-features/yogurt/\">Harvard Nutrition Source — yogurt and strained yogurt</a></li></ul>", "ingredients": [{"name": "iogurte natural integral sem açúcar, frio", "amount": "1000", "unit": "g"}], "steps": [{"title": "Prepare a peneira", "content": "Lave e higienize tigela e peneira. Forre com pano fino limpo próprio para alimentos sobre uma tigela funda. O pano deve ficar longe do líquido que escorrer.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-01.webp", "image_alt": "Prepare a peneira — Iogurte grego caseiro escorrendo iogurte natural"}, {"title": "Adicione o iogurte", "content": "Coloque o iogurte frio sem bater. Junte as pontas do pano e cubra sem apertar. Não adicione leite nem água.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-02.webp", "image_alt": "Adicione o iogurte — Iogurte grego caseiro escorrendo iogurte natural"}, {"title": "Escorra na geladeira", "content": "Refrigere a 4 °C ou menos por 4–6 horas. Confira a textura após 4 horas e retire o soro antes de alcançar a peneira. Não escorra à temperatura ambiente.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-03.webp", "image_alt": "Escorra na geladeira — Iogurte grego caseiro escorrendo iogurte natural"}, {"title": "Alise e guarde", "content": "Transfira para recipiente limpo e mexa delicadamente. Para afinar, misture um pouco do soro reservado. Tampe e mantenha frio. O tempo total considera 6 horas de drenagem.", "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/paso-04.webp", "image_alt": "Alise e guarde — Iogurte grego caseiro escorrendo iogurte natural"}], "category": "Sobremesas", "course": "Sobremesas", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 10, "cook_time_minutes": 0, "total_time_minutes": 370, "servings": 5, "image_url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/yogur-griego-casero/portada.webp", "alt": "Iogurte grego caseiro escorrendo iogurte natural"}], "video_urls": [], "keywords": ["Iogurte grego caseiro escorrendo iogurte natural"], "nutrition": {"calories": 97, "protein_g": 9, "carbs_g": 4, "fat_g": 5, "serving_size": "1 de 5 porções, cerca de 100 g", "estimated": true, "note": "Estimativa por porção; rendimento, umidade e marcas alteram os valores.", "source": "USDA FoodData Central generic plain whole-milk Greek yogurt proxy", "method": "Reference finished strained yogurt per 100 g: 97 kcal, 9 g protein, 4 g carbohydrate, 5 g fat. Five 100 g portions assume 500 g yield from 1000 g natural yogurt. Whey excluded; no exact nutrient retention measured. Draining and starting yogurt alter composition."}, "seo": {"title": "Iogurte grego caseiro escorrendo iogurte natural", "description": "Transforme iogurte natural em iogurte grego sem espessantes. Fotos mostram a drenagem na geladeira, rendimento aproximado e formas de aproveitar o soro.", "author": "Néstor Bastidas", "image_alt": "Iogurte grego caseiro escorrendo iogurte natural", "image_variants": ["https://manualdecocina.com/recetas/yogur-griego-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/yogur-griego-casero/portada-16x9.webp"], "faq": [{"q": "Preciso de outra cultura?", "a": "Não. Parte-se de iogurte já fermentado; a receita do natural explica como começar pelo leite."}, {"q": "Quanto mais escorre, mais rende?", "a": "Ao contrário: fica mais espesso e o peso final diminui."}], "additional_time_minutes": 360}, "published": false, "editorial_status": "ready"}]$payload$::jsonb;
foods jsonb := $foods$[{"slug": "yogur-natural", "name": "Yogur natural"}]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "yogur-natural", "alias": "yogur natural entero sin azúcar, frío"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),'Ingrediente para elaboraciones lácteas domésticas.','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>1 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
FOR v IN SELECT * FROM public.recipes WHERE recipe_group_id=group_id LOOP
 PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
 UPDATE public.recipes SET editorial_status='published' WHERE id=v.id;
END LOOP;
END $dairy$;
SELECT language,public_path,published FROM public.recipes WHERE recipe_group_id=(SELECT recipe_group_id FROM public.recipes WHERE language='es' AND slug='yogur-griego-casero') ORDER BY language;
